/** Build diagrams/bundle.js and src/main.jsx → assets/app.js (committed; GitHub Pages serves them statically). */
import * as esbuild from 'esbuild';
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';

// bundle.js is the file:// fallback for fetching diagrams/*.mmd over HTTP.
const manifest = JSON.parse(readFileSync('diagrams/manifest.json', 'utf8')).map((m) => ({
  ...m,
  file: `diagrams/${m.id}.mmd`,
  source: readFileSync(`diagrams/${m.id}.mmd`, 'utf8'),
}));
writeFileSync('diagrams/bundle.js',
  '// generated by build.mjs — do not edit; edit the .mmd files instead\n'
  + `window.TWEAKPELE_DIAGRAMS = ${JSON.stringify(manifest, null, 1)};\n`);
console.log('bundled', manifest.length, 'diagrams');

const result = await esbuild.build({
  entryPoints: ['src/main.jsx'],
  bundle: true,
  minify: true,
  format: 'iife',
  target: ['es2019'],
  outfile: 'assets/app.js',
  jsx: 'automatic',
  define: { 'process.env.NODE_ENV': '"production"' },
  legalComments: 'none',
  metafile: true,
  banner: { js: '/* tweakpele UI — built from src/ with esbuild: npm run build */' },
});

const sizes = {};
for (const [file, info] of Object.entries(result.metafile.outputs)) {
  if (!file.startsWith('assets/')) continue;
  sizes[file] = (info.bytes / 1024).toFixed(1) + ' KB';
}
console.log('built', sizes);

// Bust GitHub Pages CDN/browser cache for CSS/JS after each build.
const jsHash = createHash('sha256').update(readFileSync('assets/app.js')).digest('hex').slice(0, 8);
const cssHash = createHash('sha256').update(readFileSync('tweakpele.css')).digest('hex').slice(0, 8);
let html = readFileSync('index.html', 'utf8');
html = html
  .replace(/href="\.\/tweakpele\.css(?:\?v=[^"]*)?"/, `href="./tweakpele.css?v=${cssHash}"`)
  .replace(/src="\.\/assets\/app\.js(?:\?v=[^"]*)?"/, `src="./assets/app.js?v=${jsHash}"`);
writeFileSync('index.html', html);
console.log('cache-bust', { css: cssHash, js: jsHash });
